-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('f51906fd-c292-505c-b243-c452c6e84e63'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('5355e2fa-5393-58d2-99ad-0404c1de038e'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('3ef45a7c-958a-5ab6-853d-d809e578dbf4'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('20272c6a-c121-5c3a-beda-0a5172f3b9de'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('305d7a99-d21e-5848-9327-99c995531580'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('ed0ab391-248d-5be3-af2e-2c02c2504cca'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('9081fad5-b389-5a67-9c11-c04717dfe0e0'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('3e98dcf6-994f-5c69-aeab-d6fd48c7aee5'::uuid, '28532e72-bde0-5522-8425-622f346b2c65'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('a3f72e8f-11db-59d4-94f5-1a4e46c0741f'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('a5654c7a-f8dd-5887-bcd6-a3e541d60134'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('2bf7eb99-f270-59c8-b64e-4fb0963ee2a0'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('a966fb8b-43a0-55c0-811f-f236e8bcc99d'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('f7d4bc9e-35df-5043-b39b-17242d8ca4e6'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Comment dit-on « ne… plus » ?', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no fumo* : je ne fume plus. *Todavía no* signifie « pas encore ».', 5),
    ('b9533073-7673-5ea9-b176-771d064f22af'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["Sino","Pero","Porque","Aunque"]'::jsonb, 0, '*No es francés sino español.* *Pero* oppose sans rectifier.', 6),
    ('e0e2ccde-f88b-5268-a1db-3c65e4488d42'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('6d99ee20-cfba-5510-9f0b-03d60aa58be5'::uuid, '9700c030-3e91-575e-9290-efd79add981c'::uuid, 'Devant un verbe conjugué, « sino » devient…', 'mcq', '["Sino que","Sino de","Sino a","Sino el"]'::jsonb, 0, '*No canta sino que grita.*', 8),
    ('a086d0dd-cb69-5318-975a-902824143540'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('088cb755-d31d-51cb-8787-4496a3c86682'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('81521632-26dc-555f-9fe5-60d44e213065'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('aa57f2be-5067-565f-adc3-d786c707a61d'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('63a047e8-0e93-5a4a-bf1c-74e348a0c5fd'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'Après « No conozco a nadie que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au gérondif"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini.', 5),
    ('022f803f-10c5-50b7-a64e-06d8a4386b47'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'Pour renvoyer à une idée entière, on emploie…', 'mcq', '["Lo que","El que","Quien","Cuyo"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 6),
    ('d0579b52-2b8d-51e9-a4d1-54ed0492db6e'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('80b707b2-e547-5c57-ad17-c9f348dedc07'::uuid, '25602306-55f6-5f59-9ec0-a6d9cee52adf'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('552e2302-977c-53d2-a781-f5bc8aacef97'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Après « Quiero que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au conditionnel"]'::jsonb, 0, 'La volonté commande le subjonctif : *Quiero que vengas.*', 1),
    ('e5ec6de5-ad96-5b60-bec1-f9c5a6e0bdca'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('285a6357-5b60-5c42-8708-28b175913513'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('45618e16-2df1-5263-8f1f-113282e11e6d'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Après « Es necesario que… », on emploie…', 'mcq', '["Le subjonctif","L’indicatif","Le gérondif","Le participe"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif : *que estudies*.', 4),
    ('6db49e7d-a8b9-516f-9850-f738c352ec72'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('22ed9460-f0e0-5168-9115-7d6d6dcf1e83'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('9d56e0a0-f26a-5eec-8765-d745cd00eb28'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('df193406-6449-5661-94da-cc6ad0856aa1'::uuid, '30819681-7d84-597a-ba75-b37050411c5d'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('64c17d0d-df50-566f-9907-837b598566bb'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('4dc16b8f-ffaa-5f24-b6fc-42d9c90bb6ef'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('dfc4acac-392e-5313-bf43-ba8f2f21d09b'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('12a95dd2-7e13-5c8f-995e-22e2b0047855'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('a61999d0-6f2f-531e-b78d-eb46af23bf9b'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('3cd2dfbc-76fe-5762-9056-419f6f129837'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('29a0e177-8b00-5284-b737-bfee5b9c3fde'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('82de3128-7196-5693-8d5d-ee3478a86149'::uuid, 'affd4bb2-2b68-5a09-9efd-3ff1505f483c'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('7c341107-3b19-5995-a258-f2c4f9c80c00'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('4e0c471d-7f47-5856-9876-4e3e69feef6b'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('2577a880-20c2-5b89-add2-e0d0a8393bc4'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('e0b35d24-4d11-538c-b542-44ec36fff414'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('81d044b9-224b-5e5c-a446-e1390ad75e0e'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('e7995222-a9d6-5280-b2e4-9cdbbe313f21'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('168a0d37-793d-59db-a07d-501cb912aa6c'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('0b517cc0-f01c-5195-ae0f-d0a637ee407b'::uuid, 'a0262158-b0c5-5fed-ba7b-2e6ee1e85a54'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('e6cbbd31-5bb7-536f-b1b7-c32c3e3e28e7'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('866e2bb4-a8cf-5255-bff3-8c1838bb0258'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('5fb887c6-7dd4-51fa-8820-e09d189b5232'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('fa7b332f-6713-5134-86dc-93db06cb6b0c'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('4eb3f506-3026-5878-8e50-eb113f54b884'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('8f0c082a-a148-506b-b339-c190e7a5b5fa'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('860353b2-ed29-5291-a44b-1aa7967ad2fd'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, 'Comment traduire « qu’est-ce que c’est ? » ?', 'mcq', '["¿Qué es esto?","¿Qué es este?","¿Qué es ésta?","¿Qué es aquel?"]'::jsonb, 0, 'La chose n’étant pas identifiée, on emploie le neutre.', 7),
    ('873285dc-088c-598d-8c6c-df787b053921'::uuid, '1911926a-d40a-5090-9348-2f84c68d6ad3'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('55a4842d-4748-54c2-994a-f4ba5d7b3f90'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('c4e84c9b-0aaa-5a74-8e58-06aeed63beb9'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('b593950f-89b9-5678-afd0-2c5c8bc526d2'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('72bd4ad4-249c-58c8-8de2-0663139ba951'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('68df013c-961b-5a38-ba1e-fde86d3e0729'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('a7d35266-703e-5397-a817-f650e5b7e427'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('a8c74362-8e0c-558f-8e09-995782f91acb'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('16b0d7d9-3f4c-5583-b98b-13957906ab8b'::uuid, 'a7450f0b-580d-586a-bd2f-5ebef1867834'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('5974382e-ad53-5388-a976-655396c080dc'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('d1c01570-2c25-576e-bebc-721bf800938c'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('ac792282-3867-58c7-b448-3f34789809a7'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('19068b35-de81-5f6a-a466-00b069bfe8fd'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('b8acc94b-0d9e-5e4b-a21b-370a2e954748'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, 'Comment traduire « pour moi » ?', 'mcq', '["Para mí","Para yo","Por yo","Para me"]'::jsonb, 0, 'Après préposition, *yo* devient *mí* et *tú* devient *ti*.', 5),
    ('46ae61ba-5ad9-5688-916a-b3f880382493'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('bbf89ce2-9634-5e09-83fc-57ecb70435bd'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, 'Après « entre » et « según », quel pronom emploie-t-on ?', 'mcq', '["Tú et yo","Ti et mí","Te et me","Usted seulement"]'::jsonb, 0, '*Entre tú y yo*, *según tú* : ces prépositions font exception.', 7),
    ('7846d9be-809e-55e8-b68e-e0c3ecc9aecc'::uuid, '6f3e11da-06b0-5f67-81c0-bec23fe985ce'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('aa6ceafc-fb02-5f17-9e00-ff8ac67a8a29'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('be88f8d4-d0d3-5a0f-979d-c46d3db06bcb'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Que devient « le » devant « lo » ?', 'mcq', '["Se","Lo","La","Les"]'::jsonb, 0, '*Se lo doy* : « le lo doy » n’existe pas.', 2),
    ('67c3274b-246c-5ad9-ab24-df66314e3d9b'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('958389a8-202a-5147-92d1-1b50ab5ecbb4'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('fe99012b-376a-5833-80f5-b3f060612768'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('3b0626b5-e26f-5ec3-b4b6-243cbccc0ce9'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('cc684055-db1d-5688-b18e-381f2355b735'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('a4e2a392-b7b3-597e-ba28-e15ccf5ec227'::uuid, '65a87ac6-c321-55f1-8b66-c745728ee5a9'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('d26fc245-650e-5f22-b428-0445b0df94f7'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('447e7926-06b8-5576-a4ac-7a094c071017'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Comment traduire « je me lave les mains » ?', 'mcq', '["Me lavo las manos","Me lavo mis manos","Lavo mis manos","Me lavo mías manos"]'::jsonb, 0, 'Corps et vêtements prennent l’article défini, pas le possessif.', 2),
    ('89633d06-2d21-5828-b385-27cfca79af24'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('60d5c7ed-90d6-5a2e-8169-9c357c93d8e3'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('ce585e12-bdac-5324-9beb-c9bdaad28296'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('d2d04d2c-0ce5-5d87-8d2c-b543abbd9870'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('2edd384f-0677-5944-8c56-e60339c198cc'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Comment traduire « il a mal à la tête » ?', 'mcq', '["Le duele la cabeza","Le duele su cabeza","Duele su cabeza","Tiene mal su cabeza"]'::jsonb, 0, 'Le pronom *le* porte déjà l’information de possession.', 7),
    ('704d947f-c5e2-581f-8c09-1e9a1c98b237'::uuid, '3e3c1e50-36da-5483-93d1-fd91a36c3305'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('8052eb4c-f7c5-5d5e-936c-eb7f8d34cbe8'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('cf357bfb-8212-5db4-a1c1-5bc92ee6c046'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('0343f44e-e78d-5717-b147-a2df3bba18f8'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, 'Quel relatif s’emploie uniquement pour des personnes ?', 'mcq', '["Quien","Que","Cuyo","Donde"]'::jsonb, 0, '*La persona con quien hablo.*', 3),
    ('85a69f10-89b1-5811-9b81-febc10ba96fc'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('2a8e5985-3d87-59f4-9211-d69e869eb839'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('23ca398b-4a8a-5400-b47c-8c695f6ac4e5'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('5541ab3e-6069-5f5c-bac3-fac3b20aa022'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, 'Comment demander « à qui est-ce ? »', 'mcq', '["¿De quién es?","¿Cuyo es?","¿Que es de?","¿Quien es de?"]'::jsonb, 0, '*Cuyo* ne s’emploie jamais dans une question.', 7),
    ('788dad40-e0ac-551b-8248-9f61e46eda4b'::uuid, '39213505-bb7a-521c-aad7-6a1fb044abbe'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('e72f8cdb-a894-5996-8c80-36c950b9fc7c'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('31cfae81-9fa4-5626-a615-cedf43a293ec'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('780abac7-9758-5420-b3cc-99ec89087c65'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('8f8b5ba1-d050-513b-898c-f9207d24db95'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('18165444-1185-5cca-b492-ae825a1deb6d'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('3f2c68a2-03f1-5ad9-b13a-0f5579ecafb5'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('60f7468a-66b7-5df6-b6f8-6c4e8f91ebba'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('3dbaee25-05f6-54cd-990d-e8c98162edf5'::uuid, '3b1dd461-b10c-5e37-b081-7f63c990a59a'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('d64f42a9-0c91-59be-b679-77b1d64c2f34'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Comment traduire « aussi grand que toi » ?', 'mcq', '["Tan alto como tú","Tanto alto como tú","Más alto como tú","Tan alto que tú"]'::jsonb, 0, '*Tan* devant un adjectif, *como* comme second terme.', 1),
    ('0ebfade9-58aa-5df1-97a0-aa3f5236cb92'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Comment traduire « autant de livres que toi » ?', 'mcq', '["Tantos libros como tú","Tan libros como tú","Tanto libros como tú","Más libros como tú"]'::jsonb, 0, '*Tanto* devant un nom, et il s’accorde : *tantos libros*.', 2),
    ('b45d80df-05a1-5c8a-ae11-cd88d35f23e1'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('7615da2b-ca4a-50b1-9e91-6ae64b35ae91'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('09417665-3e7d-571c-8d54-5ac158e6a7c1'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('efb15efb-5f10-5600-8460-6abef6873d5b'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Quel est le comparatif de « malo » ?', 'mcq', '["Peor","Más malo","Menor","Mal"]'::jsonb, 0, 'Comme *bueno → mejor*, *grande → mayor*, *pequeño → menor*.', 6),
    ('8d08432a-b5a7-5974-be5a-84776419ff8e'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('7b938091-8fa2-58d1-9f56-a1218b940660'::uuid, '8e3960f9-7add-510f-bf96-4ed6b6580f41'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('68b919c7-5b23-5ed5-b050-1cdafcd5424f'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Comment traduire « le plus grand du monde » ?', 'mcq', '["El más grande del mundo","El más grande en el mundo","El mucho grande del mundo","El más grande que el mundo"]'::jsonb, 0, 'Le complément du superlatif relatif se construit avec *de*.', 1),
    ('82f22c08-e991-5699-b683-301b2518b3fa'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('4f591452-40e1-5be7-a320-f1f426d9408b'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Quel est le superlatif absolu de « rico » ?', 'mcq', '["Riquísimo","Ricísimo","Rikísimo","Ricoísimo"]'::jsonb, 0, 'Le c devient qu pour conserver le son [k].', 3),
    ('04be9ee0-a1f5-5978-bdd4-bb73cfeaa421'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('c8edb339-278f-5b75-923c-4e66d0e29978'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('775b2f52-2e87-5adf-adab-0ff3b0d790d5'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('630a4e48-395c-5cf0-8f53-922c0f78f609'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('958dd900-09a1-51ac-935c-fc19615f714f'::uuid, '696a030e-2044-5059-8aa1-0acbb9843782'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('36679672-438a-50a7-87a6-8d32bee7a1ae'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, 'Quelle est la forme apocopée de « bueno » devant un nom masculin ?', 'mcq', '["Buen","Bue","Buenó","Bon"]'::jsonb, 0, '*Un buen amigo*, mais *un amigo bueno* garde la forme pleine.', 1),
    ('8d7779fb-42bb-57c1-926c-a247605b99e0'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('8728ba2a-4ff2-57a9-b82f-108c2e522279'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, 'Comment dit-on « cent euros » ?', 'mcq', '["Cien euros","Ciento euros","Cientos euros","Cien de euros"]'::jsonb, 0, '*Ciento* s’apocope devant un nom, et devant *mil* et *millones*.', 3),
    ('37d2958e-b164-5960-9894-60508a2493b1'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('f66df4ee-6d2f-57aa-9847-677fa8ad9595'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('8fe00773-0160-5687-8b4b-789e3b6465dd'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('c8433783-09e8-5285-a217-2494dbd30c55'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('474cc8ae-bfb9-5964-ac23-df091f5de4ab'::uuid, '65c354e8-1802-59e9-8012-9792ee2e1fa1'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('22d68bfe-83a4-5936-a4c4-f39b6cf9ddb3'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('5370814b-0274-5e80-a02d-8ddfba8824eb'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('1e053917-b6c7-5074-8636-7cf2de6f4de3'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('2e5018ba-eac4-5e70-9903-8c99e87f9e6b'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('54c18393-7886-542a-a384-8a1bd24232f0'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('7aaf4afc-38a7-5d28-96ba-5238c963e293'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('59408bd8-8cd7-5a3a-b304-dc603f6370c1'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('e6f7278e-2b7f-54bd-b4ff-d83e4f2db106'::uuid, '8a500ea3-004f-56e8-abfa-d8c879bb0171'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('ddff34f7-aa31-5668-b527-a76bed964d1a'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('afccca73-a135-5407-a1de-ba8cfb596817'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('b7f1d8fd-e2b1-5a2c-b9fc-2f544a663a5d'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('b4fb26e3-826a-56b6-855d-6f70418e315d'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('52489906-b469-5e94-b9f2-51860cc4a5b9'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('17c536a8-c350-56c8-a874-ebcee7d450b3'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('6f724404-8a25-5583-ab25-fa668667426f'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('6ef6688a-f391-5c35-90da-b048bd7a17fb'::uuid, '7dc8661f-27f8-5600-843f-1388ad77255f'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('27b0731f-768d-50bd-8ffa-737f79d3634a'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('7b88392f-19e0-5023-a990-c4ccd4b56f92'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('203206f0-96cf-5f31-8e49-683d0d574288'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('c743c9b4-bb33-5755-8d61-49e4030a8e9c'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('f93bfb82-5d3d-57e7-ae0a-22c2a8dbafe5'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('391b7b01-9d04-58b7-988d-9a83fbb6a970'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('306e03ae-962e-59ee-bb9f-7fe8c40e3cca'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('4d9a44a4-1dcf-528c-8ae7-c85ebe1c9e23'::uuid, 'd8a35181-bafe-50ad-8eff-f1ce9b3a7639'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('45dd8564-58d0-588a-a1b8-713a37556fb1'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('92c81118-14ee-5ccc-81bc-16ba7b847c95'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('6a686715-6ca7-5ffc-9ce5-df6d6b45ab49'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('f5f95591-35e3-55df-b500-e62cc7549592'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('92d4400d-9eac-5d8f-86d5-f49dccea7eef'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('6363252d-04ee-5668-b715-ac98360cf00d'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('ac90a048-66b4-55ed-b3fd-62b5d8ddbf27'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('e66ff93e-fc62-50b3-9c2e-14e8ddf9d84e'::uuid, '783e1e86-6100-5a52-a96b-26d2946fcf0f'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('23233275-0cc3-5217-8948-b6e4514de49a'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('fca16bc8-455b-5b57-a584-ac6965a70d26'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('5fe243ef-d65e-5f88-8870-0a092f50cd5b'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('57f0bfd3-35ea-5c6d-a018-330aebe852a8'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('84e6f578-1c61-58c0-9373-3572c5c588d8'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('e9500cf3-c04c-56f1-a301-363a0519ee27'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('0e6efb98-c019-5f31-bece-110cf4f5f0c0'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('7ffdbf6a-cfdc-510e-8d73-e09cad2be9ec'::uuid, '79f1c823-bbc6-5b27-a47d-89439af8eb6d'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('ecb463aa-32a1-52b1-8ec2-2a4418c57f46'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('766231f6-a367-535e-8856-b6589b84b093'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('e5b69a4d-7922-58e1-851a-99d23d21785d'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('0bcb83a5-ae4f-5dbb-b3fe-e6bb09f3b7ff'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('cb9f5aec-142c-5b20-b73a-2e7012d39c35'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('f8878ced-0caf-5d46-9ece-b1edfa0cf1e5'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('308eb1c9-a3ee-52bb-9b41-c0a68a289a0f'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('11b83776-d0b4-53fb-90b5-82e175f88bca'::uuid, '3cfc1e1b-ed10-5560-b49b-1c7eb9481e25'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('3476e60e-6062-5619-af24-b92641484b07'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('e6588fec-3058-5260-8b06-eb7247e09123'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('f9e312ec-d32b-5750-91b6-4716ffc3e281'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('181f0306-354f-5937-9994-ba6c620b5c09'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('7012197c-5455-516e-a544-8730b8ac8176'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('21436caa-8431-5ccc-ac28-54415458d38a'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('2bc8298c-3701-5c73-999f-33ae96354604'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('06a4d689-1e14-5c3b-8149-3841c72129da'::uuid, 'a267783a-b9a2-58eb-85f5-aeab922dca56'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('d32ee560-f1d2-5638-a7aa-077a9061f0f4'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('3e3d1518-b6f7-59a1-a89f-b2122f16f504'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('ddecc366-fdea-5833-a31c-382cf0600a5e'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('30758ce2-1d8d-5eda-bcfa-885b16752573'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('5e68e0c0-7c1a-5566-855f-a951c59627fe'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('349c462c-ca3b-5ef8-a2cc-fd33908a9de3'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('d2081963-e50e-5dc5-ba2b-4a5557e783d9'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('7d040932-b9cf-59fd-aa44-6b878d9244d2'::uuid, '9ae92b05-ffbc-5cff-ba15-56b8bd3e2325'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('f9c7d203-dff7-557d-b896-9159d72fab60'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('520f8a73-9d42-5bef-aba9-0e9b79a74702'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('9813eb2e-6119-5e0c-badb-807eea2d1b68'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('70c3f3d1-2a61-5dbd-88fc-4bfe44d9bf51'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('31aa5227-82c8-5710-a62d-82f4cb2cdfa7'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('e7fb43b6-ba2f-5486-8ca1-d2f75734c4de'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('c0272787-033f-502f-bd8a-1b37f113ac3d'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('7bd4aff7-537d-5070-b03f-7425a388e79e'::uuid, '260ce296-4841-5146-9c9e-1ac0484f33d7'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('fd6ee671-91b6-5994-87a5-ea6b82d5ffeb'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('1350c180-1c89-5319-a270-478586d26622'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('ffd73a1b-e6ac-596b-adbd-e41f6db5572c'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('a9916204-8ed6-5742-8ba4-8612da11836c'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('5f9a0911-3a62-5d74-ab39-c18348fc05e9'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('b8f92720-49dc-5692-b56c-3909949932a4'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('4b111c52-54a8-575c-a724-b0f7f959633c'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('fc75e614-e998-50d9-a4dd-1c0f9f6394e0'::uuid, '6faae632-d021-5f21-aff1-ff5842d03ba5'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('ac7e8fc4-7341-592b-bcd3-67b45bd9f270'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('b22d5957-4e7a-54bb-9b97-e8b6165e8864'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('f7bbc2ef-40d9-5c12-85cd-12696c20f391'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('6a374734-54e5-524d-bf3f-6bf74a2b3f9f'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('93ee303d-91d9-56fc-8580-fb0ee0f73956'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('3011ec29-7705-518c-aee4-17617448d276'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('2022c245-3ccb-5c5c-a071-3bb501593bd5'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('60fa1a12-400a-53a4-8b36-1e4f67cc3148'::uuid, '3f12813a-9207-5cb0-8c13-14baeb399b08'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('3139d8d3-18ae-5f1f-814e-4bb964b49cbb'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('3e36e8a2-029d-5fd4-9295-3ea07d25555b'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('2bdd141e-d5d4-5842-9550-9ec15af7134f'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('581369b0-43e7-5106-ae59-bffa7f051c03'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('868f8e62-9f19-5cda-afc2-59991c77359c'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('4737d9a4-fd18-50df-a5fd-ef747b36ed93'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('08d01892-e631-5bf3-8ece-09bcd69a8aa2'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('efdd200a-ab7f-5456-832e-37d26b93d58b'::uuid, '87844177-6df4-5163-95b0-9999be6b8086'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('ab8a5384-aa29-567d-a65c-8bd4f1305faa'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('9bdf3684-6cb7-50f3-ac26-40c425e50849'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('302a6f74-a42c-543b-8d38-b00ff85baed0'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('43485512-1a58-5482-8900-a7a6e088610d'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('faf5c162-19d0-5434-b03d-8691cbfa260f'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('731f1447-8443-500a-9bae-8bf826e860f0'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('a4a0dd27-008d-55e2-a020-cb0b8a249358'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('3bd167be-8593-5970-bef0-1daeca4b66fb'::uuid, '49f2eaa6-ce83-5c20-ade5-0e77130b7dfe'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('30503f4b-a468-5f58-895a-8265108234fe'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('a5e14e8a-f393-58b6-a660-6ed079c0e0b2'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('3177b804-2591-5d1e-b14d-ba2bf8159198'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('b9c95312-fce0-5c50-b354-5ee06d93d90f'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('ea2135c6-82d8-5c5b-aa25-71945ebc30c4'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('7ac48cef-17c2-5501-98c4-4e85b83267ae'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
    ('93765d88-56d9-510a-a4c9-ea057c76289c'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Quelle conjonction est toujours suivie du subjonctif ?', 'mcq', '["Para que","Porque","Aunque toujours","Ya que"]'::jsonb, 0, 'Comme *antes de que*, *sin que*, *a menos que*.', 7),
    ('75ee84c0-3659-5bbb-b926-4ef98783682c'::uuid, 'd00a0eee-1607-503d-9cfb-bfab0f4cb7fc'::uuid, 'Quel est le subjonctif présent de « ir » ?', 'mcq', '["Vaya","Vaiga","Iría","Fuera"]'::jsonb, 0, 'L’un des six irréguliers dont la 1re personne ne finit pas par -o.', 8),
    ('91c6c195-95c9-517d-8e46-883fca4311e9'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'Combien de verbes sont irréguliers à l’imparfait ?', 'mcq', '["Trois : ser, ir, ver","Aucun","Six","Dix"]'::jsonb, 0, '*Era*, *iba*, *veía* — la seule liste courte de la conjugaison espagnole.', 1),
    ('63c522d7-abd8-5e86-9d65-bcbf320fac1e'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'Quelle est la terminaison de l’imparfait des verbes en -ar ?', 'mcq', '["-aba","-ía","-ió","-aría"]'::jsonb, 0, 'Les -er et -ir font *-ía*.', 2),
    ('3b9de24b-2f86-5e60-9aa8-cb15f9e360e5'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('0edf4468-7353-5ae1-b7a1-0f9b20649d66'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('4d3014a6-7ba8-500b-a5d9-acf875ceb005'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('2cc4a92e-085a-5b1c-9011-12d32a928263'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('ed5478fe-27a4-5d42-a607-71d81644f260'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('47593b1b-e796-54b5-ac92-ac0a7f3dcac2'::uuid, '58ac9f1f-5850-504f-8aea-002ce53dd79d'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('2f9c8d8b-5b56-5daa-8e94-2a74f8226059'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('cd389145-3349-5a13-9d88-418a8f90e750'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('8e827d72-f613-51c9-8989-6428704e1475'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('9b88027d-20e1-5e97-9bca-c075c185f8b8'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
    ('e4afddd3-ee9b-518a-a496-285b0ad6a347'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'Quelle est la différence entre « Hoy he ido al cine » et « Ayer fui al cine » ?', 'mcq', '["Le premier appartient à une période non achevée","Aucune","Le premier est plus soutenu","Le second est un plus-que-parfait"]'::jsonb, 0, 'Le passé simple coupe du présent, le passé composé raccroche.', 5),
    ('1de7e5a2-ac79-58fe-9569-50f87ceb8aee'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('8ff240b5-9992-5890-9f1f-b145fd033a35'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('aad1f60c-f115-57be-ba4d-c8afba8f8e7e'::uuid, '723a7549-efa7-50a2-8754-73cfbbf73c1e'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('81d32b78-759f-5ad7-aefc-768dee423879'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('555cc9ba-f9e2-51cd-83a5-364eb9024898'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('4b274286-4607-5170-a192-199bcf4fb737'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('9dc1f1af-4d93-59c8-8656-54bb241b4848'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('a0636381-3f05-55b0-9616-22d1d6ad322e'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('9c0a59a7-f3a0-5175-b706-2f38e77ddefe'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('38d14880-ba9c-5285-ae64-296a4c06e4b8'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('98dbce75-1cdc-5eac-a7f1-9b2f32cb9125'::uuid, '53693762-3757-5fa7-8481-91cb65d040c7'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('f4d544b4-d1af-5936-9935-686323921618'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('30ded188-c14a-5da0-85d5-b8368f7f1d58'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('0f71f358-27d8-51cd-b949-8e3b8fe99bb8'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('11c1654a-1e58-5326-90d9-20429750ea65'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('e0a05f3e-205a-5702-87c6-2242fd45ed58'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('1acc74b5-4599-5784-88ea-ebbaac0ce0d2'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('970511db-dfca-5925-9f5f-3444440ab53a'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('8586dfa1-a576-586b-b88f-d1b2bed3aea0'::uuid, '706bf499-4fe0-58f1-a915-a4cffcce02b2'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 312 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 312 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
